'use strict';
const stopEditorBeforeSearch=editStop;
editStop=function(tid,sid,draft){stopEditorBeforeSearch(tid,sid,draft);const t=tripById(tid);if(!t)return;const host=document.createElement('section');host.innerHTML='<label>搜索景点位置（中文 / English）<input id="place-query" placeholder="例如：金门大桥 / Golden Gate Bridge" maxlength="180"></label><button class="outline-btn" id="search-place">搜索定位</button><div id="place-results" aria-live="polite"></div><p class="hint">按城市附近搜索，选择结果即可定位。地图数据：© OpenStreetMap / Photon、Wikipedia。</p>';$('#pick-new-stop-map').closest('details').before(host);$('#place-query').value=draft?.name||$('#stop-name-new').value||$('#stop-en-new').value;let generation=0,controller;
 const search=async()=>{const query=$('#place-query').value.trim();if(query.length<2)return;controller?.abort();controller=new AbortController();const token=++generation,results=$('#place-results');results.textContent='正在搜索…';try{const r=await fetch('/api/places?'+new URLSearchParams({q:query,lat:t.coord[1],lon:t.coord[0]}),{signal:controller.signal});const data=await r.json();if(token!==generation||!results.isConnected)return;if(!r.ok)throw Error(data.error);results.innerHTML=data.results?.length?data.results.map((x,i)=>`<button class="place-result outline-btn" data-place="${i}" style="display:block;width:100%;text-align:left;margin-top:8px"><strong>${esc(x.name)}</strong><small style="display:block">${esc(x.address)}</small></button>`).join(''):'没有找到附近的匹配地点，请换个名称或使用英文搜索。';results.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const x=data.results[+b.dataset.place];$('#stop-lat-new').value=x.coord[1];$('#stop-lng-new').value=x.coord[0];if(!$('#stop-name-new').value)$('#stop-name-new').value=x.name;if(!$('#stop-en-new').value)$('#stop-en-new').value=x.en||x.name;results.textContent='已定位：'+x.name+' · '+x.coord[1].toFixed(5)+', '+x.coord[0].toFixed(5);});}catch(e){if(e.name!=='AbortError'&&results.isConnected)results.textContent=e.message||'搜索失败，请重试。';}};
 $('#search-place').onclick=search;$('#place-query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search();}};
 for(const id of ['stop-name-new','stop-en-new'])$('#'+id).addEventListener('change',()=>{$('#place-query').value=$('#'+id).value;search();});
};
const bindBeforePageDeletion=bindStudioEvents;
bindStudioEvents=function(t,s,token){bindBeforePageDeletion(t,s,token);const button=document.createElement('button');button.id='studio-delete-page';button.className='text-btn';button.textContent=s.design.pages.length>1?'删除此页':'清空此页';button.title='保留素材库中的原照片和视频，可撤销';$('#studio-add-page').after(button);button.onclick=()=>{snapshot();const i=studioContext.index,removed=s.design.pages.splice(i,1)[0];const kept=new Set(s.design.pages.flatMap(p=>p.elements.filter(e=>e.kind==='media').map(e=>e.mediaId)));s.design.excluded=[...new Set([...(s.design.excluded||[]),...removed.elements.filter(e=>e.kind==='media'&&!kept.has(e.mediaId)).map(e=>e.mediaId)])];if(!s.design.pages.length)s.design.pages.push({id:uid(),elements:[]});studioChanged();openMediaSettings(t.id,s.id,Math.max(0,i-1));toast('页面已移除，原素材保留。可点击“撤销”恢复。');};};
